from pathlib import Path
import json,hashlib
base=Path(__file__).resolve().parents[2]; src=base/'source'; out=base/'audit'
rows=[]
def add(file,claim,ranges,missing,reused):
 lines=(src/file).read_text().splitlines(); ev=[]
 for a,b in ranges:
  assert 1<=a<=b<=len(lines)
  ev.append(dict(file=file,startLine=a,endLine=b,excerpt='\n'.join(lines[a-1:b])))
 rows.append(dict(file=file,claim=claim,scope='Named local handlers and rendering read manually; consumer integration remains UNKNOWN; no runtime or security testing',auditDepth='SEMANTIC_SOURCE_REVIEW',evidence=ev,missingProof=missing,reusedPattern=reused,runtimeStatus='NOT_EXECUTED',sourceSha256=hashlib.sha256((src/file).read_bytes()).hexdigest()))
add('apps/web/src/components/BoardEditor.tsx','Resolves BOM into editorStore scratch state on module ID/composition fingerprint/preset changes; optionChoices/catalog are read through latest refs but are not effect dependencies. Resolution errors load an empty editor. Original resolved parts underpin override derivation; pose/dimension/duplicate/remove controls call editorStore and optional onOverridesChange bridges edits to parent draft. Cleanup clears editor.',[(79,96),(104,136),(172,210)],'Whether compositionKey includes all relevant option/catalog changes, parent override persistence and exact occurrence identity require caller/store review and tests; no inference that duplicate/remove persist merely because scratch changes. 3D/2D interaction/undo and resolution error distinction remain UNKNOWN.','Existing editorStore + BoardCanvas/BoardPropertiesPanel/Furniture3DViewer composition; reusing child names does not certify their full behavior.')
add('packages/ui/src/optionGroups/PricePreviewGate.tsx','Calls canShowPricePreview using required group codes and chosen options. Missing groups become polite live-status list with label-or-code fallback; children render only when gate.ok. No price calculation, role check or persistent mutation.',[(20,50)],'Helper validity versus retired choices, caller required-group completeness, stale prices and assistive announcements remain UNKNOWN.','Reused presentation gate; readiness is not authoritative price/release validation.')
add('packages/ui/src/placeholder.tsx','Placeholder returns provided children or null; contains no route, workflow, data loading or feature implementation.',[(1,6)],'Consumer routing and any business capability inferred from this export are UNKNOWN; no functional feature coverage follows from placeholder existence.','Passthrough React wrapper only.')
add('packages/ui/src/purchasing/MaterialPlanningPanel.tsx','Displays derived material coverage and estimated board counts; released state short-circuits to badge. Capability defaults true and must be set by shell. Derive/reserve/shortage PO dispatch supplied callbacks. Regular release button is not disabled by releaseReady; incomplete checks display separate reason-required override action whose draft clears immediately after callback dispatch.',[(19,33),(46,88),(104,135),(143,175),(179,230),(239,248)],'Authoritative release/override rejection and durable audit, callback pending/error behavior, shell canManage assignment and unit/label completeness remain UNKNOWN. No bypass claim: regular command may be rejected server-side.','Reused callback-owned mutation boundary; draft reset/absence of busy is same pattern as InstallationJobPanel, not a new global finding.')
add('packages/ui/src/security/SecurityScreen.tsx','Inline enrollment/management actions use shared stepUp.run security_admin; await API result before clearing enrollment/showing recovery codes or reloading factors. Verify distinguishes invalid/expired errors; loading and management errors render alerts. Copy recovery codes catches clipboard failures and leaves codes readable; acknowledgment clears local codes. QR cancellation ignores late generation, manual secret derives from in-memory enrollment URI; failed QR generation stays null and UI presents generating placeholder.',[(55,98),(100,181),(185,194),(215,264),(293,328),(339,372),(416,425)],'This supplements existing primary-screen review only: shared step-up modal behavior, cross-session unmount/reset, clipboard denial feedback and concurrent commands remain UNKNOWN here. No MFA/security probing or new security finding; existing backend/API evidence applies only to its named scope.','Existing shared useStepUp/MFAEnrollmentHint and primary SecurityScreen fragment reused; inline source does not certify server MFA enforcement.')
add('packages/ui/src/usability/UsabilityBenchmarkPanel.tsx','Flag is captured on mount; disabled returns null and no refresh interval runs. Enabled panel refreshes every500ms with cleanup, derives latest open task from event history and provides facilitator start/complete/abandon/help/error/session-close/reset actions. Export downloads JSON; clipboard path awaits result and provides fallback. These are facilitator annotations, not automatic proof participants completed workflows.',[(39,77),(80,120),(122,147),(197,220),(249,316),(349,359),(362,405)],'Recorder storage/telemetry privacy, interaction capture coverage, real-participant observation and performance/benchmark validity remain UNKNOWN; the real label on beginUsabilitySession is caller metadata, not evidence a study happened.','Existing usabilityBenchmark recorder helpers; panel is local facilitator control and must not inflate product UX acceptance metrics.')
assert {r['file'] for r in rows}==set(json.loads((out/'scripts/web-secondary-last-files.json').read_text()))
(out/'data/web-secondary-last.json').write_text(json.dumps(dict(sourceCommit='316df57c7c3c9d5470b5a3f22b39fffeacfd7676',scope='Six final unique secondary/inline files; static only; no new global findings',fragments=rows),ensure_ascii=False,indent=2)+'\n')
(out/'evidence/web-secondary-last.md').write_text('# Final secondary/inline component review\n\nStatic only; no product changes or runtime execution. Reused patterns do not certify consumer behavior.\n\n'+'\n\n'.join('## '+r['file']+'\n'+r['claim']+'\n\nReused: '+r['reusedPattern']+'\n\nUNKNOWN: '+r['missingProof']+'\n\nEvidence: '+', '.join(f"{e['file']}:{e['startLine']}–{e['endLine']}" for e in r['evidence']) for r in rows)+'\n')
print(len(rows),'files;',sum(len(r['evidence']) for r in rows),'validated ranges')
